/**
 * Phase 3 of docs/superadmin-control-plan.md: the owner corrects any account.
 *
 * Players, coaches and judges are edited through their Mongoose documents
 * (`doc.set` + `save`), so the schema validators and pre-save hooks run
 * exactly as they do for the person themself — a player's Player ID is
 * generated by the same hook, an email clash hits the same unique index.
 * Admins are edited through SuperAdminService.updateAdmin, which already
 * protects the owner's account.
 *
 * Every write takes a reason and is recorded by CorrectionService. Field edits
 * are undoable from History; a password reset, sign-out and deactivation are
 * recorded but undone by doing the opposite.
 *
 * @module services/superadmin/accounts-admin.service
 */

const crypto = require('crypto');
const mongoose = require('mongoose');
const { ValidationError, NotFoundError, ConflictError, BusinessRuleError } = require('../../errors');
const { requireReason } = require('./correction.service');
const { checkAgeGroup, groupLabel } = require('../../utils/data/age-eligibility.util');
const { recordLogout } = require('../../utils/security/token-invalidation.util');
const { normalizeEmail } = require('../../utils/validation/sanitization.util');

const TYPES = ['player', 'coach', 'judge', 'admin'];

/** What the owner may change, per account type. Anything else in a body is ignored. */
const EDITABLE = {
  player: ['firstName', 'lastName', 'dateOfBirth', 'gender', 'email', 'emailType', 'guardian', 'phone'],
  coach: ['firstName', 'lastName', 'email', 'phone'],
  judge: ['firstName', 'lastName', 'email', 'phone'],
  admin: ['name', 'email'],
};

const MODEL = { player: 'Player', coach: 'Coach', judge: 'JudgeAccount', admin: 'Admin' };

const nameOf = (doc) => (doc?.name || [doc?.firstName, doc?.lastName].filter(Boolean).join(' ') || 'Account');
const escapeRx = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const idOf = (v) => (v && v._id ? String(v._id) : v ? String(v) : null);

/** Ten readable characters: no 0/O/1/l/I, always a digit and an upper-case letter. */
function temporaryPassword() {
  const letters = 'abcdefghjkmnpqrstuvwxyz';
  const upper = 'ABCDEFGHJKMNPQRSTUVWXYZ';
  const digits = '23456789';
  const all = letters + upper + digits;
  const pick = (set) => set[crypto.randomInt(set.length)];
  const chars = [pick(upper), pick(digits), ...Array.from({ length: 8 }, () => pick(all))];
  for (let i = chars.length - 1; i > 0; i -= 1) {
    const j = crypto.randomInt(i + 1);
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return chars.join('');
}

class AccountsAdminService {
  constructor({ correctionService, superAdminService, competitionRepository, tokenService, logger }) {
    this.corrections = correctionService;
    this.superAdmin = superAdminService;
    this.competitions = competitionRepository;
    this.tokens = tokenService;
    this.logger = logger;
  }

  _type(type) {
    if (!TYPES.includes(type)) throw new ValidationError(`Account type must be one of ${TYPES.join(', ')}`);
    return type;
  }

  _model(type) {
    return mongoose.model(MODEL[this._type(type)]);
  }

  async _load(type, id) {
    if (!mongoose.isValidObjectId(id)) throw new ValidationError('Invalid account id');
    const doc = await this._model(type).findById(id);
    if (!doc) throw new NotFoundError(type === 'judge' ? 'Judge account' : type[0].toUpperCase() + type.slice(1));
    return doc;
  }

  /** The fields the edit drawer shows. Never a password or code. */
  view(type, doc) {
    const o = doc.toObject ? doc.toObject() : doc;
    const base = {
      _id: o._id, type, name: nameOf(o), email: o.email || null, phone: o.phone || null,
      isActive: o.isActive !== false, createdAt: o.createdAt || null,
    };
    if (type === 'player') {
      Object.assign(base, {
        firstName: o.firstName, lastName: o.lastName, loginId: o.loginId || null, emailType: o.emailType || 'self',
        guardian: o.guardian || null, dateOfBirth: o.dateOfBirth || null, gender: o.gender || null,
      });
    } else if (type === 'admin') {
      Object.assign(base, { role: o.role });
    } else {
      Object.assign(base, { firstName: o.firstName, lastName: o.lastName });
    }
    return base;
  }

  /** Search every kind of account by name, email or Player ID. */
  async search({ q, type } = {}) {
    const text = String(q || '').trim();
    if (text.length < 2) throw new ValidationError('Type at least two characters');
    const rx = new RegExp(escapeRx(text.slice(0, 60)), 'i');
    const parts = text.split(/\s+/).filter(Boolean).slice(0, 2).map((p) => new RegExp(`^${escapeRx(p)}`, 'i'));
    const nameOr = parts.length === 2
      ? [{ firstName: parts[0], lastName: parts[1] }, { firstName: rx }, { lastName: rx }]
      : [{ firstName: rx }, { lastName: rx }];
    const types = type ? [this._type(type)] : TYPES;
    const results = await Promise.all(types.map(async (t) => {
      const or = t === 'admin' ? [{ name: rx }, { email: rx }] : [...nameOr, { email: rx }, ...(t === 'player' ? [{ loginId: rx }] : [])];
      const rows = await this._model(t).find({ $or: or }).limit(25).lean();
      return rows.map((r) => this.view(t, r));
    }));
    return results.flat().sort((a, b) => a.name.localeCompare(b.name)).slice(0, 60);
  }

  async get(type, id) {
    const doc = await this._load(type, id);
    const out = this.view(type, doc);
    if (type === 'player') out.entries = await this._entries(doc);
    return out;
  }

  /**
   * Edit an account. `payload.reason` is required. For a player,
   * `regenerateLoginId: true` issues a new Player ID from the (new) name and
   * date of birth; `fixAgeGroups: true` moves squad entries the new date of
   * birth or gender no longer allows into the lowest group the meet runs that
   * they may enter (entries already scored are reported, not moved).
   */
  async update(actor, type, id, payload = {}) {
    const reason = requireReason(payload.reason);
    if (type === 'admin') {
      const before = await this._load('admin', id);
      const body = Object.fromEntries(EDITABLE.admin.filter((f) => payload[f] !== undefined).map((f) => [f, payload[f]]));
      await this.superAdmin.updateAdmin(id, { ...body, reason }, actor.id);
      return this.get('admin', before._id);
    }

    const doc = await this._load(type, id);
    const before = doc.toObject();
    const fields = EDITABLE[type].filter((f) => payload[f] !== undefined);
    const updates = {};
    for (const field of fields) {
      let value = payload[field];
      if (field === 'email') value = value ? normalizeEmail(value) : undefined;
      if (field === 'dateOfBirth') {
        const date = new Date(value);
        if (Number.isNaN(date.getTime())) throw new ValidationError('Date of birth is not a valid date');
        value = date;
      }
      if (field === 'guardian' && value && typeof value === 'object') {
        value = { name: value.name ?? null, email: value.email ? normalizeEmail(value.email) : null, phone: value.phone ?? null };
      }
      if (typeof value === 'string') value = value.trim();
      updates[field] = value;
    }
    if (payload.regenerateLoginId && type !== 'player') throw new ValidationError('Only players have a Player ID');
    if (!fields.length && !payload.regenerateLoginId) throw new ValidationError('Nothing to change');

    doc.set(updates);
    if (type === 'player' && payload.regenerateLoginId) doc.loginId = undefined;
    try {
      await doc.save();
    } catch (error) {
      if (error?.code === 11000) throw new ConflictError('That email or Player ID is already used by another account');
      if (error?.name === 'ValidationError') throw new ValidationError(error.message);
      throw error;
    }

    const after = doc.toObject();
    const changed = [...fields, ...(payload.regenerateLoginId ? ['loginId'] : [])];
    await this.corrections.record({
      actor, entity: type, entityId: id, action: `${type.toUpperCase()}_UPDATED`, label: nameOf(after),
      reason, before, after, fields: changed, undoable: !payload.regenerateLoginId,
    });

    const out = this.view(type, doc);
    if (type === 'player') {
      out.entries = await this._entries(doc);
      if (payload.fixAgeGroups) out.moved = await this._fixAgeGroups(actor, doc, out.entries, reason);
      if (out.moved?.length) out.entries = await this._entries(doc);
    }
    return out;
  }

  /** Every squad entry of this player, with whether the age rule still allows it. */
  async _entries(player) {
    const Competition = this.competitions.model;
    const Score = mongoose.model('Score');
    const meets = await Competition.find(
      { 'registeredTeams.players.player': player._id, isDeleted: { $ne: true } },
      { name: 1, level: 1, startDate: 1, endDate: 1, ageGroups: 1, 'registeredTeams.team': 1, 'registeredTeams.players': 1 }
    ).lean();
    const out = [];
    for (const meet of meets) {
      for (const reg of meet.registeredTeams || []) {
        const entry = (reg.players || []).find((p) => idOf(p.player) === String(player._id));
        if (!entry) continue;
        const check = checkAgeGroup({ dateOfBirth: player.dateOfBirth, gender: entry.gender, ageGroup: entry.ageGroup, competition: meet });
        const offered = (meet.ageGroups || []).filter((g) => g.gender === entry.gender).map((g) => g.ageGroup);
        const suggestion = check.ok ? null : (check.eligible.find((g) => offered.includes(g)) || null);
        const scored = await Score.exists({ competition: meet._id, 'playerScores.playerId': player._id });
        out.push({
          competition: { _id: meet._id, name: meet.name, level: meet.level },
          team: idOf(reg.team), gender: entry.gender, ageGroup: entry.ageGroup,
          ageOk: check.ok, age: check.age, suggestion, scored: !!scored,
        });
      }
    }
    return out;
  }

  async _fixAgeGroups(actor, player, entries, reason) {
    const moved = [];
    for (const e of entries) {
      if (e.ageOk || !e.suggestion || e.scored) continue;
      const ok = await this.competitions.updatePlayerInRegistration(e.competition._id, e.team, player._id, { ageGroup: e.suggestion });
      if (!ok) continue;
      moved.push({ competition: e.competition.name, from: e.ageGroup, to: e.suggestion });
      await this.corrections.record({
        actor, entity: 'entry', entityId: player._id, action: 'ENTRY_PLAYER_UPDATED', label: nameOf(player),
        reason: `${reason} (age group after date-of-birth fix: ${groupLabel(e.ageGroup)} → ${groupLabel(e.suggestion)})`,
        competitionId: e.competition._id,
        before: { ageGroup: e.ageGroup }, after: { ageGroup: e.suggestion },
      });
    }
    return moved;
  }

  /** End every session the account has open, on every device. */
  async _signOut(id) {
    await this.tokens?.revokeAllRefreshTokens?.(String(id));
    await recordLogout(String(id));
  }

  /**
   * Set a temporary password, shown to the owner ONCE, and sign the account
   * out everywhere. The person changes it from their profile.
   */
  async resetPassword(actor, type, id, { reason } = {}) {
    const why = requireReason(reason);
    this._type(type);
    const doc = await this._load(type, id);
    if (type === 'admin' && doc.role === 'superadmin' && String(doc._id) !== String(actor.id)) {
      throw new BusinessRuleError('The Super Admin password is changed from your own profile');
    }
    const password = temporaryPassword();
    doc.set({ password, loginAttempts: 0, lockUntil: null });
    doc.markModified('password');
    await doc.save();
    await this._signOut(doc._id);
    await this.corrections.record({
      actor, entity: type, entityId: id, action: 'PASSWORD_RESET_BY_OWNER', label: nameOf(doc), reason: why,
    });
    return { temporaryPassword: password, login: doc.loginId || doc.email || null };
  }

  async signOutEverywhere(actor, type, id, { reason } = {}) {
    const why = requireReason(reason);
    const doc = await this._load(type, id);
    await this._signOut(doc._id);
    await this.corrections.record({ actor, entity: type, entityId: id, action: 'SIGNED_OUT_EVERYWHERE', label: nameOf(doc), reason: why });
    return { signedOut: true };
  }

  /**
   * Deactivate or reactivate. Coaches are never deactivated (the requests of
   * the players they registered are theirs alone to decide), and the owner's
   * own account is never deactivated.
   */
  async setActive(actor, type, id, { isActive, reason } = {}) {
    const why = requireReason(reason);
    const active = isActive === true || isActive === 'true';
    if (type === 'coach' && !active) throw new BusinessRuleError('Coaches cannot be deactivated');
    const doc = await this._load(type, id);
    if (type === 'admin' && doc.role === 'superadmin') throw new BusinessRuleError('The Super Admin account cannot be deactivated');
    if ((doc.isActive !== false) === active) throw new BusinessRuleError(active ? 'Already active' : 'Already deactivated');
    await this._model(type).updateOne({ _id: doc._id }, { $set: { isActive: active } });
    if (!active) await this._signOut(doc._id);
    await this.corrections.record({
      actor, entity: type, entityId: id, action: active ? 'ACCOUNT_REACTIVATED' : 'ACCOUNT_DEACTIVATED', label: nameOf(doc), reason: why,
      before: { isActive: !active }, after: { isActive: active },
    });
    return this.get(type, id);
  }

  /** Undo for a field edit made here: the same update, with the old values. */
  async undoFields(actor, type, id, values, reason) {
    return this.update(actor, type, id, { ...values, reason });
  }
}

module.exports = AccountsAdminService;
module.exports.temporaryPassword = temporaryPassword;
module.exports.EDITABLE = EDITABLE;
